#!/bin/sh
# R24-Windows cross-build host-side moduleinfotool bridge (the R21/R22
# method): the SDK's post-build step invokes the PE moduleinfotool on the
# Linux host, which cannot execute (no wine in the sandbox). This wrapper
# (planted at <build>/vst3sdk/bin/moduleinfotool.exe after configure, so
# ninja treats the target as up-to-date) copies the moduleinfo.json
# generated by the IDENTICAL-variant Linux twin build -- the factory
# metadata (FUIDs, class names, parameters, version) is a compile-time
# property of the same sources with the same defines, so the Linux tool's
# output is exactly the Windows bundle's metadata.
# Usage: moduleinfotool -create -version V -path <bundle> -output <json>
set -e
PATH_ARG=""
OUTPUT_ARG=""
while [ $# -gt 0 ]; do
    case "$1" in
        -path) PATH_ARG="$2"; shift 2 ;;
        -output) OUTPUT_ARG="$2"; shift 2 ;;
        *) shift ;;
    esac
done
[ -z "$PATH_ARG" ] && exit 1
[ -z "$OUTPUT_ARG" ] && exit 1
BUNDLE="$(basename "$PATH_ARG")"
R24=/home/z/my-project/octavox-work/r24
case "$BUNDLE" in
    PitchLab_Lagrange6_Balanced.vst3) SRC="$R24/build_vst3_r24w_bal" ;;
    PitchLab_Lagrange6_FullRate.vst3)  SRC="$R24/build_vst3_r24w_full" ;;
    *) echo "moduleinfotool-host: unknown bundle $BUNDLE" >&2; exit 1 ;;
esac
SRCJSON="$SRC/VST3/Release/$BUNDLE/Contents/Resources/moduleinfo.json"
if [ ! -f "$SRCJSON" ]; then
    echo "moduleinfotool-host: missing source moduleinfo $SRCJSON" >&2
    exit 1
fi
mkdir -p "$(dirname "$OUTPUT_ARG")"
cp "$SRCJSON" "$OUTPUT_ARG"
echo "[R24W-host] moduleinfo.json copied for $BUNDLE"
